class SendLogsToHastebinAction : AdmActionBase() {
    override fun actionWithConnectionPerformed(e: AnActionEvent) {
        val project = e.project ?: return
        val hasteLink = HastebinService.getInstance(project).createHaste(readIdeaLogFile())

        if (hasteLink == null) {
            AdmNotification()
                .withTitle("Hastebin service unavailable. Try again later")
                .show(project)
            return
        }

        AdmNotification("Thanks for logs!")
            .withTitle("Logs successfully sent to Hastebin")
            .withActions(AdmNotification.Action("Copy hastebin link") { _, notification ->
                MyUtils.copyToClipboard(hasteLink)
                notification.expire()
            })
            .show(project)
    }

    override fun beforeUpdate(e: AnActionEvent) {
        e.presentation.icon = AdmIcons.Service.Hastebin
    }
}

package com.vk.admstorm.actions

import com.intellij.openapi.actionSystem.AnAction
import com.intellij.openapi.actionSystem.AnActionEvent
import com.vk.admstorm.ssh.SshConnectionService
import com.vk.admstorm.utils.extensions.pluginEnabled

/**
 * Base class for all plugin actions that require SSH connection.
 *
 * To use, implement the [actionWithConnectionPerformed] method,
 * which has the same signature as the default [actionPerformed] method.
 *
 * If the project is not vkcom, then this action will be disabled and invisible.
 */
abstract class AdmActionBase : AnAction() {
    final override fun actionPerformed(e: AnActionEvent) {
        if (e.project == null || !SshConnectionService.getInstance(e.project!!).isConnectedOrWarning()) {
            return
        }

        actionWithConnectionPerformed(e)
    }

    override fun update(e: AnActionEvent) {
        beforeUpdate(e)

        if (e.project == null || !e.project!!.pluginEnabled()) {
            e.presentation.isEnabledAndVisible = false
        }
    }

    open fun beforeUpdate(e: AnActionEvent) {}

    /**
     * Implement this method to provide your action handler.
     *
     * @param e Carries information on the invocation place
     */
    abstract fun actionWithConnectionPerformed(e: AnActionEvent)
}

package com.vk.admstorm.actions

import com.intellij.openapi.editor.SelectionModel
import com.intellij.psi.PsiElement
import com.intellij.psi.PsiFile
import com.jetbrains.php.lang.psi.PhpFile
import com.jetbrains.php.lang.psi.PhpPsiUtil

/**
 * Base class for actions that run on a specific PHP [PsiElement].
 *
 * To use, override the [actionPerformed] method and the [errorHint] parameter.
 */
abstract class PhpPsiElementAction<T : PsiElement>(klass: Class<T>) :
    SelectionBasedPsiElementAction<T>(klass, PhpFile::class.java) {

    override fun getElementFromSelection(file: PsiFile, selectionModel: SelectionModel): T? {
        val selectionStart = selectionModel.selectionStart
        val selectionEnd = selectionModel.selectionEnd
        return PhpPsiUtil.findElementOfClassAtRange(file, selectionStart, selectionEnd, myClass, true, true)
    }
}
